topics.description:
`try...catch...finally` looks simple, but its exact rules explain many surprising bugs.

### Syntax
```js
try {
  // code that might throw
} catch (error) {      // optional binding (ES2019): catch { ... }
  // runs only if try threw
} finally {
  // runs ALWAYS: after try, after catch, even after return/break/continue
}
```
You need at least one of `catch` or `finally`.

### Rules to remember
1. **Only synchronous errors** inside the `try` block are caught. A rejected promise or a `setTimeout` callback is *outside* the block unless you `await` it.
2. If `try` finishes normally, `catch` is skipped. If it throws, execution jumps to `catch` and the rest of `try` is skipped.
3. `finally` runs **in all cases** - even if `try` or `catch` executes `return`, `break`, `continue`, or throws again.
4. **A `return` (or `throw`) inside `finally` overrides** the earlier `return` or `throw`. This silently swallows errors - avoid it.
5. The `catch` binding is **block scoped**: `error` does not exist after the block. Variables declared with `let/const` inside `try` are not visible in `catch` or `finally` - declare them before `try`.
6. If `catch` throws, `finally` still runs, and the new error propagates.
7. `return` value is computed *before* `finally` runs, but a later `finally` can still change an object it points to.

### Typical uses of finally
Hide a loading spinner, release a lock, close a file or database connection, restore state - things that must happen on success and on failure.

### Optional catch binding
When you do not need the error: `try { JSON.parse(x) } catch { return null }`. Do this only when ignoring it is truly correct; otherwise log it.

### Performance and style
Keep the `try` block small - wrap only the risky call, not 100 lines, so you know what failed. Do not use exceptions for normal control flow.

examples.code:
function a() { try { return "try"; } finally { console.log("finally runs after return is evaluated"); } }
function b() { try { return "try"; } finally { return "finally"; } }           // overrides
function c() { try { throw new Error("lost"); } finally { return "swallowed"; } } // error swallowed!
function d() {
  try { throw new Error("first"); }
  catch (e) { throw new Error("from catch"); }
  finally { console.log("cleanup always runs"); }
}
console.log(a());
console.log(b());
console.log(c());
try { d(); } catch (e) { console.log("caught:", e.message); }

for (let i = 1; i <= 3; i++) {
  try {
    if (i === 2) continue;
    console.log("body", i);
  } finally {
    console.log("finally", i);       // runs even for the continue
  }
}
function f() {
  const state = { n: 0 };
  try { return state; } finally { state.n = 99; }   // object is shared, so the caller sees 99
}
console.log(f().n);
function g() {
  let n = 0;
  try { return n; } finally { n = 99; }             // primitive copied before finally
}
console.log(g());

let result;                    // declare outside so it is visible after the block
try {
  const parsed = JSON.parse("{bad json}");
  result = parsed;
} catch {
  result = "fallback";
}
console.log(result);

try {
  setTimeout(() => { console.log("timer callback runs later, outside the try block"); }, 0);
  Promise.reject(new Error("async failure")).catch((e) => console.log("caught by .catch:", e.message));
} catch (e) {
  console.log("never reached");
}
(async () => {
  try { await Promise.reject(new Error("awaited")); }
  catch (e) { console.log("caught with await:", e.message); }
  finally { console.log("async finally"); }
})();

function level3() { throw new RangeError("deep failure"); }
function level2() { console.log("level2 start"); level3(); console.log("never printed"); }
function level1() { try { level2(); } catch (e) { console.log("level1 caught", e.name); throw e; } }
try { level1(); } catch (e) { console.log("top caught", e.message, "| same object:", e instanceof RangeError); }

function readConfig() { return JSON.parse("{oops"); }

function loadWrapped() {
  try { return readConfig(); }
  catch (e) { throw new Error("Could not load config", { cause: e }); }
}
try { loadWrapped(); }
catch (e) {
  console.log(e.message);
  console.log("cause:", e.cause.name, "-", e.cause.message);
}

function onlySyntax(fn) {
  try { return fn(); }
  catch (e) { if (e instanceof SyntaxError) return "bad json"; throw e; }
}
console.log(onlySyntax(() => JSON.parse("{")));
try { onlySyntax(() => null.x); } catch (e) { console.log("rethrown unknown:", e.name); }

const required = (name) => { throw new TypeError(name + " is required"); };
function createUser(name = required("name"), age = 18) { return { name, age }; }
console.log(createUser("Asha"));
try { createUser(); } catch (e) { console.log(e.name + ": " + e.message); }

class AppError extends Error {
  constructor(message, { code = "E_APP", status = 500, cause, details } = {}) {
    super(message, { cause });
    this.name = "AppError";
    this.code = code;
    this.status = status;
    this.details = details;
    if (typeof Error.captureStackTrace === "function") Error.captureStackTrace(this, this.constructor);
  }
  toJSON() { return { name: this.name, code: this.code, status: this.status, message: this.message, details: this.details }; }
}
class NotFoundError extends AppError {
  constructor(what) { super(what + " not found", { code: "E_NOT_FOUND", status: 404 }); this.name = "NotFoundError"; }
}
class ValidationError extends AppError {
  constructor(fields) { super("Validation failed", { code: "E_VALIDATION", status: 422, details: fields }); this.name = "ValidationError"; }
}

const errors = [new NotFoundError("User 42"), new ValidationError({ email: "invalid" }), new AppError("boom")];
for (const e of errors) {
  console.log(e.name, e.status, e instanceof AppError, e instanceof NotFoundError, e instanceof Error);
}
console.log(JSON.stringify(errors[1]));
console.log(String(errors[0]));
console.log(errors[0].stack.split("\n")[0]);

class HttpError extends Error {
  constructor(status, message) { super(message); this.name = "HttpError"; this.status = status; }
}
function handle(e) {
  if (e instanceof HttpError) {
    if (e.status === 401) return "redirect to login";
    if (e.status === 404) return "show not-found page";
    if (e.status >= 500) return "show retry banner";
    return "show message: " + e.message;
  }
  throw e;
}
for (const s of [401, 404, 503, 400]) console.log(s, "->", handle(new HttpError(s, "HTTP " + s)));

class Forgot extends Error {}                               // no name set
const f = new Forgot("hi");
console.log(f.name, String(f), f.constructor.name);          // name is "Error"

class Good extends Error { get name() { return "Good"; } }   // prototype-level name
console.log(String(new Good("hi")));

// instanceof across realms is not possible here, so many libraries also set a flag:
class Flagged extends Error { constructor(m) { super(m); this.isFlagged = true; } }
const plain = { isFlagged: true, message: "from another realm" };
console.log(new Flagged("x") instanceof Flagged, plain instanceof Flagged, plain.isFlagged === true);

console.log(JSON.stringify(new Error("lost")), JSON.stringify({ ...new Error("lost") }));

function queryDb() { throw new Error("connection refused (ECONNREFUSED)"); }
function loadUser(id) {
  try { return queryDb(); }
  catch (e) { throw new Error("Could not load user " + id, { cause: e }); }
}
function renderProfile(id) {
  try { return loadUser(id); }
  catch (e) { throw new Error("Profile page failed", { cause: e }); }
}

try { renderProfile(7); }
catch (err) {
  let level = 0;
  for (let e = err; e; e = e.cause) console.log("  ".repeat(level++) + (level > 1 ? "caused by: " : "") + e.message);
  console.log("root cause:", err.cause.cause.message);
}

function serialize(err, seen = new Set()) {
  if (!(err instanceof Error)) return err;
  if (seen.has(err)) return "[circular cause]";
  seen.add(err);
  return {
    name: err.name,
    message: err.message,
    code: err.code,
    cause: err.cause === undefined ? undefined : serialize(err.cause, seen),
  };
}
const root = new TypeError("fetch failed");
const mid = new Error("service unavailable", { cause: root });
const top = new Error("checkout failed", { cause: mid });
console.log(JSON.stringify(serialize(top), null, 2));

const loop = new Error("a"); loop.cause = loop;
console.log(JSON.stringify(serialize(loop)));

const e1 = new Error("with string", { cause: "plain text reason" });
const e2 = new Error("with object", { cause: { status: 503, retryAfter: 30 } });
console.log(e1.cause, e2.cause.retryAfter);
console.log("cause" in new Error("no cause"), "cause" in e1);
console.log(Object.getOwnPropertyDescriptor(e1, "cause").enumerable);

function process(n) {
  if (n % 3 === 0) throw new RangeError("item " + n + " is divisible by 3");
  if (n % 5 === 0) throw new TypeError("item " + n + " is divisible by 5");
  return n * 2;
}
const ok = [], errors = [];
for (const n of [1, 2, 3, 4, 5, 6]) {
  try { ok.push(process(n)); } catch (e) { errors.push(e); }
}
console.log("ok:", ok);
try { if (errors.length) throw new AggregateError(errors, errors.length + " items failed"); }
catch (e) { console.log(e.message); e.errors.forEach((x) => console.log(" -", x.name, x.message)); }

const task = (name, ok) => new Promise((res, rej) => setTimeout(() => (ok ? res(name) : rej(new Error(name + " failed"))), 5));

(async () => {
  const results = await Promise.allSettled([task("upload-a", true), task("upload-b", false), task("upload-c", false)]);
  const done = results.filter((r) => r.status === "fulfilled").map((r) => r.value);
  const failed = results.filter((r) => r.status === "rejected").map((r) => r.reason);
  console.log("succeeded:", done);
  try { if (failed.length) throw new AggregateError(failed, failed.length + " uploads failed"); }
  catch (e) { console.log(e.name, "->", e.errors.map((x) => x.message)); }
})();

const mirror = (name, ok, ms) => new Promise((res, rej) => setTimeout(() => (ok ? res(name + " data") : rej(new Error(name + " down"))), ms));

(async () => {
  console.log(await Promise.any([mirror("eu", false, 5), mirror("us", true, 15), mirror("asia", true, 25)]));
  try { await Promise.any([mirror("eu", false, 5), mirror("us", false, 10)]); }
  catch (e) { console.log(e instanceof AggregateError, e.errors.map((x) => x.message).join(", ")); }
})();

async function retry(fn, { retries = 3, baseMs = 10, shouldRetry = () => true } = {}) {
  let attempt = 0;
  while (true) {
    try { return await fn(attempt); }
    catch (err) {
      if (attempt >= retries || !shouldRetry(err)) throw err;
      const delay = baseMs * 2 ** attempt;              // 10, 20, 40...
      console.log("attempt " + (attempt + 1) + " failed (" + err.message + "), retry in " + delay + "ms");
      await new Promise((r) => setTimeout(r, delay));
      attempt++;
    }
  }
}
let calls = 0;
const flaky = async () => { calls++; if (calls < 3) throw Object.assign(new Error("503"), { transient: true }); return "success after " + calls + " calls"; };
retry(flaky, { shouldRetry: (e) => e.transient }).then(console.log);

const bad = async () => { throw new TypeError("bug: x is not a function"); };
retry(bad, { shouldRetry: (e) => !(e instanceof TypeError) }).catch((e) => console.log("not retried:", e.message));

async function loadWidgets(loaders) {
  const results = await Promise.allSettled(loaders.map((l) => l()));
  return results.map((r, i) => r.status === "fulfilled"
    ? { ok: true, data: r.value }
    : { ok: false, message: "Widget " + (i + 1) + " is unavailable" });
}
const weather = async () => "sunny 24C";
const news = async () => { throw new Error("news API down"); };
const stocks = async () => ["ACME +2%"];
loadWidgets([weather, news, stocks]).then((w) => w.forEach((x) => console.log(JSON.stringify(x))));

function withDefault(fn, def) { try { return fn(); } catch { return def; } }
console.log(withDefault(() => JSON.parse("oops"), { theme: "light" }));

class CircuitBreaker {
  constructor(fn, { failureThreshold = 2, cooldownCalls = 2 } = {}) {
    Object.assign(this, { fn, failureThreshold, cooldownCalls, failures: 0, skipped: 0 });
  }
  async call(...args) {
    if (this.failures >= this.failureThreshold && this.skipped < this.cooldownCalls) {
      this.skipped++;
      throw new Error("circuit open: skipping call");
    }
    try { const r = await this.fn(...args); this.failures = 0; this.skipped = 0; return r; }
    catch (e) { this.failures++; this.skipped = 0; throw e; }
  }
}
let healthy = false;
const breaker = new CircuitBreaker(async () => { if (!healthy) throw new Error("service down"); return "ok"; });
(async () => {
  for (let i = 1; i <= 6; i++) {
    if (i === 6) healthy = true;
    try { console.log(i, await breaker.call()); } catch (e) { console.log(i, e.message); }
  }
})();

class ValidationError extends Error {
  constructor(issues) { super(issues.length + " validation issue(s)"); this.name = "ValidationError"; this.issues = issues; }
}
function validateUser(input) {
  const issues = [];
  if (typeof input.name !== "string" || input.name.trim() === "") issues.push({ field: "name", message: "name is required" });
  if (!Number.isInteger(input.age) || input.age < 0 || input.age > 120) issues.push({ field: "age", message: "age must be an integer 0-120, got " + JSON.stringify(input.age) });
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(input.email ?? "")) issues.push({ field: "email", message: "email is not valid" });
  if (issues.length) throw new ValidationError(issues);
  return { name: input.name.trim(), age: input.age, email: input.email };
}
try { validateUser({ name: " ", age: "abc", email: "nope" }); }
catch (e) { console.log(e.name + ": " + e.message); e.issues.forEach((i) => console.log(" -", i.field + ":", i.message)); }
console.log(validateUser({ name: "Asha ", age: 30, email: "asha@example.com" }));

function assert(cond, msg = "Assertion failed") { if (!cond) throw new Error("Assertion failed: " + msg); }

function average(list) {
  assert(Array.isArray(list), "list must be an array");
  assert(list.length > 0, "list must not be empty");
  return list.reduce((a, b) => a + b, 0) / list.length;
}
console.log(average([2, 4, 6]));
try { average([]); } catch (e) { console.log(e.message); }

function area(shape) {
  switch (shape.type) {
    case "circle": return +(Math.PI * shape.r ** 2).toFixed(2);
    case "square": return shape.side ** 2;
    default: throw new Error("Unhandled shape: " + shape.type);
  }
}
console.log(area({ type: "circle", r: 2 }), area({ type: "square", side: 3 }));
try { area({ type: "triangle" }); } catch (e) { console.log(e.message); }
console.assert(1 === 2, "console.assert only logs and does not throw");
console.log("still running");

// Turn untrusted input into a trusted type exactly once.
function parsePort(value) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1 || n > 65535) throw new RangeError("port must be 1-65535, got " + JSON.stringify(value));
  return n;
}
for (const v of ["8080", "0", "80.5", "abc", "", null]) {
  try { console.log(JSON.stringify(v), "->", parsePort(v)); }
  catch (e) { console.log(JSON.stringify(v), "->", e.name + ": " + e.message); }
}

topics.description:
Exceptions are **invisible** in a function signature: nothing tells the caller that `parseAge()` may fail. The **Result** (or *Either*) pattern makes failure part of the return value.

```js
const ok  = (value) => ({ ok: true,  value });
const err = (error) => ({ ok: false, error });

function parseAge(text) {
  const n = Number(text);
  return Number.isInteger(n) && n >= 0 ? ok(n) : err("invalid age: " + text);
}

const r = parseAge("42");
if (r.ok) use(r.value); else show(r.error);
```

### Where it shines
- **Expected** failures: validation, parsing, "not found", business rules.
- Pipelines where each step may fail (map / flatMap over results).
- Code where forgetting to handle an error should be visible (TypeScript discriminated unions enforce it).

### Where exceptions are better
- **Unexpected** failures (bugs, out-of-memory, programmer errors).
- Deep call stacks where you want to handle the error far away from where it happened.
- Interop: all built-ins and most libraries throw.

### Variants
| Style | Shape |
|---|---|
| Result object | `{ ok, value, error }` |
| Go-style tuple | `const [err, data] = await to(promise)` |
| Either | `Left(error)` / `Right(value)` with `map/flatMap` |
| Option / Maybe | value or `null` (no error info) |

### Tuple helper for async code
```js
async function to(promise) {
  try { return [null, await promise]; } catch (e) { return [e, null]; }
}
const [error, user] = await to(fetchUser(id));
if (error) return showError(error);
```
This avoids nested `try/catch` blocks, but make sure you check `error` every time.

### Combining both
Use Result at your module boundaries for expected failures and exceptions inside for the unexpected; convert with `tryCatch(fn)`.

examples.code:
const ok = (value) => ({ ok: true, value });
const err = (error) => ({ ok: false, error });
const map = (r, f) => (r.ok ? ok(f(r.value)) : r);
const flatMap = (r, f) => (r.ok ? f(r.value) : r);

const parseJson = (text) => { try { return ok(JSON.parse(text)); } catch (e) { return err("bad json: " + e.message); } };
const getAge = (obj) => (Number.isInteger(obj.age) ? ok(obj.age) : err("age missing or not an integer"));
const adult = (age) => (age >= 18 ? ok(age) : err("must be 18+"));

for (const text of ['{"age": 30}', '{"age": 12}', '{"name": "x"}', "{oops"]) {
  const result = flatMap(flatMap(parseJson(text), getAge), adult);
  console.log(text, "=>", result.ok ? "OK " + result.value : "ERR " + result.error);
}
console.log(map(ok(2), (x) => x * 10), map(err("no"), (x) => x * 10));

async function to(promise) {
  try { return [null, await promise]; }
  catch (e) { return [e, null]; }
}
const getUser = (id) => new Promise((res, rej) => setTimeout(() => (id === 1 ? res({ id, name: "Asha" }) : rej(new Error("user " + id + " not found"))), 5));

(async () => {
  for (const id of [1, 2]) {
    const [error, user] = await to(getUser(id));
    if (error) { console.log("failed:", error.message); continue; }
    console.log("loaded", user.name);
  }
})();

function tryCatch(fn) {
  try { return { ok: true, value: fn() }; }
  catch (error) { return { ok: false, error }; }
}
const a = tryCatch(() => JSON.parse('{"x":1}'));
const b = tryCatch(() => JSON.parse("{"));
const c = tryCatch(() => decodeURIComponent("%"));
console.log(a.ok, a.value);
console.log(b.ok, b.error.name);
console.log(c.ok, c.error.name);

window.addEventListener("error", (event) => {
  // event.error is the Error object (null for cross-origin "Script error.")
  report({ type: "error", message: event.message, source: event.filename, line: event.lineno, col: event.colno,
           stack: event.error && event.error.stack });
});

window.addEventListener("unhandledrejection", (event) => {
  const reason = event.reason;
  report({ type: "unhandledrejection", message: reason && reason.message ? reason.message : String(reason),
           stack: reason && reason.stack });
  // event.preventDefault();   // would hide the default console error
});

function report(payload) {
  const body = JSON.stringify({ ...payload, url: location.href, ua: navigator.userAgent, release: "1.4.2" });
  if (!navigator.sendBeacon("/api/log", body)) fetch("/api/log", { method: "POST", body, keepalive: true });
}

class ErrorBoundary extends React.Component {
  state = { hasError: false };
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error, info) { logToService(error, info.componentStack); }
  render() { return this.state.hasError ? <p>Something went wrong. <button onClick={() => location.reload()}>Reload</button></p> : this.props.children; }
}
// <ErrorBoundary><Dashboard /></ErrorBoundary>

// Node.js
process.on("unhandledRejection", (reason) => { logger.error({ err: reason }, "unhandled rejection"); });
process.on("uncaughtException", (err) => { logger.fatal({ err }, "uncaught exception"); process.exit(1); });

function createReporter({ maxPerMinute = 3 } = {}) {
  const seen = new Set();
  const sent = [];
  let count = 0;
  return {
    capture(err, context = {}) {
      const key = err.name + ":" + err.message;
      if (seen.has(key)) return "duplicate dropped";
      if (count >= maxPerMinute) return "rate limited";
      seen.add(key); count++;
      sent.push({ name: err.name, message: err.message, ...context });
      return "sent";
    },
    sent,
  };
}
const r = createReporter({ maxPerMinute: 2 });
console.log(r.capture(new TypeError("x is undefined")));
console.log(r.capture(new TypeError("x is undefined")));
console.log(r.capture(new RangeError("bad index"), { page: "/cart" }));
console.log(r.capture(new Error("third distinct")));
console.log(r.sent);

function inner() { throw new Error("deep problem"); }
function middle() { inner(); }
function outer() { middle(); }
try { outer(); } catch (e) {
  const lines = e.stack.split("\n");
  console.log("first line:", lines[0]);
  const frames = lines.slice(1).filter((l) => l.trim().startsWith("at "));
  const names = frames.map((l) => l.trim().split(" ")[1]);
  console.log("function names:", names.slice(0, 3).join(" <- "));
  console.log("has more frames:", frames.length > 3);
}

if ("stackTraceLimit" in Error) {
  console.log("default limit:", Error.stackTraceLimit);
  Error.stackTraceLimit = 2;
  function a() { return new Error("limited"); }
  function b() { return a(); }
  const e = b();
  console.log("frames kept:", e.stack.split("\n").filter((l) => l.trim().startsWith("at ")).length);
  Error.stackTraceLimit = 10;
}
if (typeof Error.captureStackTrace === "function") {
  const target = { name: "Fake", message: "not an Error" };
  Error.captureStackTrace(target);
  console.log(typeof target.stack, target.stack.split("\n")[0]);
}

const users = [{ id: 1, name: "Asha", age: 31 }, { id: 2, name: "Ben", age: 17 }];
console.log("users:", users);
console.error("something failed (shows as red in DevTools)");
console.warn("deprecated API");
console.assert(users.length === 3, "expected 3 users, got " + users.length);
console.count("render"); console.count("render");
const snapshot = structuredClone(users[0]);
users[0].name = "Changed";
console.log("snapshot keeps:", snapshot.name, "| live object:", users[0].name);
console.log("%s is %d years old", "Ben", 17);

function pipeline(input) {
  const a = input.trim();
  console.log("checkpoint 1:", JSON.stringify(a));
  const b = a.split(",").map(Number);
  console.log("checkpoint 2:", b);
  const c = b.filter(Number.isFinite);
  console.log("checkpoint 3:", c);
  return c.reduce((x, y) => x + y, 0);
}
console.log("result:", pipeline(" 1,2,x,4 "));   // checkpoint 2 reveals NaN from "x"

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function save(item) { await sleep(5); if (item === 2) throw new Error("failed to save " + item); return item; }

async function bad() {
  [1, 2, 3].forEach(async (i) => { try { await save(i); } catch (e) { console.log("inside forEach:", e.message); } });
  console.log("bad() returns before anything finished");
}
async function good() {
  const results = await Promise.allSettled([1, 2, 3].map(save));
  console.log(results.map((r) => r.status));
}
bad().then(() => sleep(30)).then(good);

function loadBad(text) { try { return JSON.parse(text); } catch (e) {} }           // returns undefined, nobody knows
function loadGood(text) {
  try { return JSON.parse(text); }
  catch (e) {
    if (e instanceof SyntaxError) throw new Error("Config file is not valid JSON", { cause: e });
    throw e;
  }
}
console.log(loadBad("{"));
try { loadGood("{"); } catch (e) { console.log(e.message, "| cause:", e.cause.name); }

try { throw "a string"; } catch (e) { console.log("string throw has stack?", e.stack === undefined); }
try { throw new Error("object throw"); } catch (e) { console.log("Error throw has stack?", typeof e.stack === "string"); }

const fails = () => Promise.reject(new Error("nobody handles me"));
